        assert_eq!(actual.iter().copied().collect::<Vec<_>>(), expected.iter().copied().collect::<Vec<_>>());
        assert_eq!(actual.front(), expected.front());
        assert_eq!(actual.back(), expected.back());
        for i in 0..=N { assert_eq!(actual.get(i), expected.get(i)); }
    }
}

